function azpsBuildScriptPanel(params) {
  // Async (CMP registers it with isAsync): builds the Script Parameters
  // Dynamic Panel from the chosen script's declared inputs, served by the
  // azps-script-panel inbound webhook. Resolves "ready", "none" (the script
  // declares no inputs), "" (no script chosen yet) or "error: ...".
  //
  // SurveyJS re-evaluates this expression on many value changes, including
  // the ones this function causes (setting the state, clearing the panel),
  // so it must be idempotent: once the panel matches the chosen script it
  // resolves immediately with the cached state and touches nothing. Only a
  // different script clears, refetches and rebuilds (rebuilding steals focus).
  var TIMEOUT_MS = 45000;
  var survey = this.survey;
  var done = this.returnResult.bind(this);
  if (!survey) { done("error: no survey instance is available to the form function."); return; }
  var ITEM = "plugin-bdi-9c6bb45b";
  var scriptQ = ITEM + ".script";
  var panelQ = ITEM + ".script_parameters";
  var stateQ = "azps_panel_state";
  var panel = survey.getQuestionByName(panelQ);
  if (!panel) { done("error: this form has no " + panelQ + " panel."); return; }

  var scriptId = String((params && params[0]) || survey.getValue(scriptQ) || "");
  var cache = survey.__azpsPanel;
  if (!cache) { cache = survey.__azpsPanel = { scriptId: null, state: "", pending: null }; }

  if (cache.pending) {
    if (cache.pending.scriptId === scriptId) { cache.pending.waiters.push(done); return; }
    cache.pending.stale = true;  // the user picked another script mid-fetch
    if (cache.pending.abort) { cache.pending.abort(); }
  } else if (cache.scriptId === scriptId) {
    done(cache.state);
    return;
  }

  function clearPanel() {
    panel.fromJSON({ templateElements: [] });
    panel.title = "Script Parameters";
    panel.description = "";
    survey.clearValue(panelQ);
    panel.panelCount = 0;
  }

  function settle(request, state) {
    if (request.stale) { return; }
    if (request.timer) { clearTimeout(request.timer); }
    cache.pending = null;
    cache.scriptId = scriptId;
    cache.state = state;
    for (var i = 0; i < request.waiters.length; i++) { request.waiters[i](state); }
  }

  var request = { scriptId: scriptId, waiters: [done], stale: false, abort: null, timer: null };
  cache.pending = request;
  clearPanel();
  if (!scriptId) { settle(request, ""); return; }
  // Show the loading text (and hide the previous script's panel) while fetching.
  if (survey.getValue(stateQ) !== "") { survey.setValue(stateQ, ""); }

  var url = "/api/v3/cmp/inboundWebHooks/azps-script-panel/run/?blueprint=" + encodeURIComponent(survey.getValue("blueprint_id") || "")
    + "&script=" + encodeURIComponent(scriptId)
    + "&group=" + encodeURIComponent(survey.getValue("group") || "");
  var envId = survey.getValue(ITEM + ".env_id");
  if (envId) { url += "&env_id=" + encodeURIComponent(envId); }
  // Cache-bust: Chrome serialises identical GETs behind the first one's cache
  // lock, so a hung call would make every later re-selection hang with it.
  url += "&_=" + Date.now();

  var init = { credentials: "same-origin", cache: "no-store", headers: { "Accept": "application/json" } };
  if (typeof AbortController === "function") {
    var controller = new AbortController();
    init.signal = controller.signal;
    request.abort = function () { controller.abort(); };
    request.timer = setTimeout(function () {
      if (request.stale) { return; }
      controller.abort();
      settle(request, "error: the parameters webhook did not answer within " + (TIMEOUT_MS / 1000) + " s (see application.log for 'azps-script-panel').");
    }, TIMEOUT_MS);
  }

  fetch(url, init)
    .then(function (response) {
      return response.text().then(function (text) {
        var body = null;
        try { body = JSON.parse(text); } catch (e) { body = { error: "non-JSON reply (HTTP " + response.status + "): " + text.slice(0, 300) }; }
        return { ok: response.ok, status: response.status, body: body };
      });
    })
    .then(function (result) {
      if (request.stale) { return; }
      var spec = result.body && result.body.panel;
      if (!result.ok || !spec) {
        settle(request, "error: " + ((result.body && result.body.error) || ("HTTP " + result.status)));
        return;
      }
      var elements = spec.elements || [];
      panel.fromJSON({ templateElements: elements });
      if (spec.title) { panel.title = spec.title; }
      if (spec.description) { panel.description = spec.description; }
      if (elements.length === 0) { settle(request, "none"); return; }
      panel.minPanelCount = 1;
      panel.panelCount = 1;
      settle(request, "ready");
    })
    .catch(function (error) {
      if (request.stale || (error && error.name === "AbortError")) { return; }
      settle(request, "error: " + error);
    });
}
